/// <summary>
/// Designed by AVANADE
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationListPage, AVASQInfoFields), FormControlEventType::Clicked)]
public static void AVASQInfoFields_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormButtonControl       button = sender as FormButtonControl;
    MenuFunction            menuFunction = new MenuFunction(menuItemDisplayStr(AVASalesquotationInfoFields),MenuItemType::Display);
    Args                    args = new Args();
    SalesQuotationTable     salesQuotationTable = sender.formRun().dataSource(tablestr(SalesQuotationTable)).cursor();
    args.caller(sender);
    args.record(salesQuotationTable);
    menuFunction.run(args);        
    button.toggleValue(OnOff::On);
}

/// <summary>
///designed by AVANADE
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationListPage, AVAUpdateQuotation), FormControlEventType::Clicked)]
public static void AVAUpdateQuotation_OnClicked(FormControl sender, FormControlEventArgs e)
{
    Args    args;
    MenuFunction    menuFunction;
    SalesQuotationTable                 salesQuotationTable;
    KCS_HDMSalesQuotationTableInfoFields    infoFields;
    boolean                                 postJour;

    salesQuotationTable = sender.formRun().dataSource(tableStr(SalesQuotationTable)).cursor() as SalesQuotationTable;

    infoFields = KCS_HDMSalesQuotationTableInfoFields::find(salesquotationtable.QuotationId, true);

    if (infoFields.InfoField2 != '' && infoFields.InfoField2Finished == NoYes::No)
    {
        if (Box::yesNo(strFmt("@NDX:NXACommitInfo2", infoFields.InfoField2), DialogButton::Yes) == DialogButton::Yes)
        {
            ttsbegin;
            infoFields.InfoField2Finished = NoYes::Yes;
            infoFields.InfoField2FinishedDateTime = DateTimeUtil::getSystemDateTime();
            infoFields.InfoField2FinishedUser = curUserId();
            infoFields.update();
            ttscommit;
            postJour = true;
        }
    }
    else
    {
        postJour = true;
    }

    if (postJour)
    {
        args = new Args();
        args.record(salesQuotationTable);

        menuFunction = new MenuFunction(menuitemActionStr(SalesQuotationEditLinesForm_S_S_Action), MenuItemType::Action);

        if (menuFunction && menuFunction.checkAccessRights())
        {

            menuFunction.run(args);
        }
    }
}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationListPage, AVAeditContactPersonName), FormControlEventType::Lookup)]
public static void AVAeditContactPersonName_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    SalesQuotationTable                 salesQuotationTable;
    salesQuotationTable = sender.formRun().dataSource(tableStr(SalesQuotationTable)).cursor() as SalesQuotationTable;

    ContactPerson::lookupDirContactPerson( sender.formRun().design().controlName(formControlStr(SalesQuotationListPage, SalesQuotationTable_ContactPersonId)),
                                               salesQuotationTable.party(),
                                               sender,
                                               salesQuotationTable.ContactPersonId);
    ce.CancelSuperCall();

}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationListPage, AVAeditContactPersonName), FormControlEventType::Modified)]
public static void AVAeditContactPersonName_OnModified(FormControl sender, FormControlEventArgs e)
{
    SalesQuotationTable                 salesQuotationTable;
    salesQuotationTable = sender.formRun().dataSource(tableStr(SalesQuotationTable)).cursor() as SalesQuotationTable;
    FormStringControl                   fsc = sender;

    if (!salesQuotationTable.ContactPersonId)
    {
        if (!ContactPerson::findNameParty(salesQuotationTable.party(), fsc.text()))
        {
            salesQuotationTable.ContactPersonId = ContactPerson::findOrCreateNameParty(salesQuotationTable.party(), fsc.text()).ContactPersonId;
        }
    }
}
